\centering
\caption{Model set composition across analyses.}
\label{tab:model_sets}
\footnotesize
\resizebox{\columnwidth}{!}{%
\begin{tabular}{lcll}
\toprule
Analysis & $J$ & Model Set & Section \\
\midrule
